#nullable enable // autogenerated

using MVZ2Logic.UI;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2Logic.Models.Components
{
    [ExecuteAlways]
    [RequireComponent(typeof(SpriteRendererResolver))]
    public class AnimationSpriteSetter : ModelComponent
    {
        public override void UpdateFrame(float deltaTime)
        {
            base.UpdateFrame(deltaTime);
            UpdateSprites();
        }
        public void UpdateSprites()
        {
            if (sprites != null && sprites.Length > 0)
            {
                if (index != beforeIndex || (Application.isEditor && !Application.isPlaying))
                {
                    SetSpriteIndex(index);
                }
            }
        }
        public void SetSpritePercent(float percent)
        {
            if (sprites == null)
                return;
            SetSpriteIndex(Mathf.FloorToInt(percent * sprites.Length));
        }

        public void SetSpriteIndex(int i)
        {
            if (sprites == null)
                return;
            index = Mathf.Clamp(i, 0, sprites.Length - 1);
            beforeIndex = index;
            Sprite sprite = sprites[index];
            Renderer.SetSprite(sprite);
        }
        private SpriteRendererResolver Renderer
        {
            get
            {
                if (!sprRenderer.Exists())
                {
                    sprRenderer = GetComponent<SpriteRendererResolver>();
                }
                return sprRenderer;
            }
        }
        private SpriteRendererResolver? sprRenderer;
        public Sprite[]? sprites;
        private int beforeIndex = -1;
        [SerializeField]
        private int index = 0;
    }
}